package ru.transferservis.admin.data;
import com.google.gson.*;
import java.io.IOException;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class VehicleRuleActionTest {
    @Test public void liftbackRuleIsExplicitComfortOnlyAndAcknowledgedWithoutAliasing()throws Exception {
        VehicleRuleAction action=create(snapshot(false),"comfort",List.of("sedan","crossover","liftback"),List.of());
        assertEquals("liftback",action.body().getAsJsonArray("allowedBodyTypes").get(2).getAsString());
        assertEquals(action.bodies,action.acknowledge(ack(action)).allowedBodyTypes);
        for(String type:List.of("business","minivan"))rejects(()->create(snapshot(false),type,List.of("liftback"),List.of()));
        JsonObject forged=ack(action);forged.getAsJsonObject("rule").addProperty("vehicleClass","minivan");
        rejects(()->VehicleClassification.Rule.parse(forged,"rule_created001"));
        assertEquals(List.of("sedan"),VehicleAssessmentTest.rule().allowedBodyTypes);
    }
    static AdminAccess owner(){return VehicleAssessmentTest.owner();}
    static VehicleRuleAction.Snapshot snapshot(boolean exists)throws Exception{return new VehicleRuleAction.Snapshot(owner(),1,"Toyota","Camry",exists?VehicleAssessmentTest.rule():null);}
    static VehicleRuleAction create(VehicleRuleAction.Snapshot s,String type,List<String> bodies,List<String> conditions)throws Exception{return VehicleRuleAction.create(owner(),s,s.make,s.model,"2023",type,bodies,conditions,"Synthetic reason");}
    private interface Invalid{void run()throws Exception;}private void rejects(Invalid a)throws Exception {try{a.run();fail("Invalid rule accepted");}catch(IOException expected){}}
    static JsonObject ack(VehicleRuleAction a){JsonObject b=VehicleAssessmentTest.json("{\"ok\":true,\"requestId\":\"req_fixture001\",\"rule\":{\"version\":\"rule_created001\",\"revision\":2}}");JsonObject r=b.getAsJsonObject("rule");for(String key:List.of("make","model","minYear","vehicleClass","allowedBodyTypes"))r.add(key,a.body().get(key));JsonArray c=new JsonArray();for(int i=0;i<a.conditions.size();i++){JsonObject item=new JsonObject();item.addProperty("id","rule_created001:"+(i+1));item.addProperty("text",a.conditions.get(i));c.add(item);}r.add("conditions",c);return b;}
    @Test public void ruleBodyIsImmutableAndNewModelRequiresExplicitNullVersion()throws Exception {VehicleRuleAction a=create(snapshot(false),"comfort",List.of("sedan","crossover"),List.of());assertEquals(8,a.body().size());assertTrue(a.body().get("expectedCurrentVersion").isJsonNull());assertFalse(a.body().has("actor"));assertFalse(a.body().has("approved"));String original=a.body().toString();a.body().addProperty("role","owner");assertEquals(original,a.body().toString());assertTrue(a.key.startsWith("vehicle-rule-"));}
    @Test public void existingVersionIsPreservedAndTargetEditsRequireLookup()throws Exception {VehicleRuleAction.Snapshot s=snapshot(true);assertEquals(s.rule.version,create(s,"comfort",List.of("sedan"),List.of()).body().get("expectedCurrentVersion").getAsString());rejects(()->VehicleRuleAction.create(owner(),s,"Toyota","Different","2023","comfort",List.of("sedan"),List.of(),"reason"));rejects(()->VehicleRuleAction.create(owner(),null,"Toyota","Camry","2023","comfort",List.of("sedan"),List.of(),"reason"));}
    @Test public void dispatcherCannotAuthorEvenWithErroneousNewPermission()throws Exception {AdminAccess a=AssignmentTestData.access("vehicles.read","vehicles.verify","vehicle_rules.manage","*");assertFalse(a.canManageVehicleRules());VehicleRuleAction.Snapshot s=snapshot(false);rejects(()->VehicleRuleAction.create(a,s,s.make,s.model,"2023","comfort",List.of("sedan"),List.of(),"reason"));assertTrue(owner().canManageVehicleRules());}
    @Test public void classAndYearHaveNoInventedDefaultsOrEconomy()throws Exception {VehicleRuleAction.Snapshot s=snapshot(false);for(String y:List.of("","0","10000","2023.5"))rejects(()->VehicleRuleAction.create(owner(),s,s.make,s.model,y,"comfort",List.of("sedan"),List.of(),"reason"));for(String c:List.of("","economy"))rejects(()->create(s,c,List.of("sedan"),List.of()));rejects(()->create(s,"comfort",null,List.of()));rejects(()->create(s,"comfort",List.of(),List.of()));}
    @Test public void approvedBusinessAndComfortBodyBoundariesArePreserved()throws Exception {VehicleRuleAction.Snapshot s=snapshot(false);rejects(()->create(s,"business",List.of("crossover"),List.of()));rejects(()->create(s,"comfort",List.of("minivan"),List.of()));VehicleRuleAction.Snapshot li=new VehicleRuleAction.Snapshot(owner(),1,"Li Auto","L7",null);assertEquals("business",create(li,"business",List.of("crossover"),List.of()).vehicleClass);rejects(()->create(li,"business",List.of("sedan"),List.of()));}
    @Test public void minivanNullPolicyIsExplicitAndRemainsNullable()throws Exception {VehicleRuleAction a=create(snapshot(false),"minivan",null,List.of("Row-specific condition"));assertNull(a.bodies);assertNull(a.acknowledge(ack(a)).allowedBodyTypes);assertEquals(List.of("minivan","other"),create(snapshot(false),"minivan",List.of("minivan","other"),List.of()).bodies);}
    @Test public void conditionsRemainVerbatimAndAreNotSplitOrTrimmed()throws Exception {VehicleRuleAction a=create(snapshot(false),"comfort",List.of("sedan"),List.of("Keep; intact, / note"));assertEquals("Keep; intact, / note",a.conditions.get(0));for(List<String> c:List.of(List.of(" trailing "),List.of("line\nbreak"),List.of("same","same"),Collections.nCopies(33,"condition")))rejects(()->create(snapshot(false),"comfort",List.of("sedan"),c));}
    @Test public void conditionPayloadCannotExceedPublicSixteenKiBLimit()throws Exception {List<String> values=new ArrayList<>();for(int i=0;i<20;i++)values.add(String.format("%02d",i)+"x".repeat(998));rejects(()->create(snapshot(false),"comfort",List.of("sedan"),values));}
    @Test public void acknowledgementMustMatchEveryOriginalValueAndGeneratedConditionId()throws Exception {VehicleRuleAction a=create(snapshot(true),"comfort",List.of("sedan"),List.of("Original condition"));assertEquals("rule_created001",a.acknowledge(ack(a)).version);for(String key:List.of("make","model","vehicleClass")){JsonObject b=ack(a);b.getAsJsonObject("rule").addProperty(key,"other");rejects(()->a.acknowledge(b));}JsonObject b=ack(a);b.getAsJsonObject("rule").getAsJsonArray("conditions").get(0).getAsJsonObject().addProperty("id","foreign:1");rejects(()->a.acknowledge(b));JsonObject stale=ack(a);stale.getAsJsonObject("rule").addProperty("version",a.snapshot.rule.version);rejects(()->a.acknowledge(stale));}
    @Test public void privateUnknownFieldsAndWrongResponseTypesFailClosed()throws Exception {VehicleRuleAction a=create(snapshot(false),"comfort",List.of("sedan"),List.of());JsonObject b=ack(a);b.addProperty("privateObjectKey","PRIVATE");rejects(()->a.acknowledge(b));JsonObject wrong=ack(a);wrong.getAsJsonObject("rule").addProperty("minYear","2023");rejects(()->a.acknowledge(wrong));}
    @Test public void exactLookupRejectsCrossModelCursorAndPrivateMetadata()throws Exception {JsonObject b=VehicleAssessmentTest.json("{\"ok\":true,\"requestId\":\"req_fixture001\",\"rules\":[],\"nextCursor\":null}");assertNull(VehicleRuleAction.Snapshot.parse(owner(),1,"Toyota","Camry",b).rule);b.addProperty("nextCursor","page_next001");rejects(()->VehicleRuleAction.Snapshot.parse(owner(),1,"Toyota","Camry",b));}
}
